const access=$json.context;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(access.status!=='OK'){
 const messages={SUBMITTED:'Rapporto già inviato / Report already submitted.',UNCONFIRMED:'Invio da verificare. Contatta il FM prima di riprovare / Submission requires verification. Contact the FM before retrying.',NOT_OPEN:'Il ticket non accetta un nuovo rapporto / This ticket is not accepting another report.'};
 return [{json:{httpCode:access.status==='SUBMITTED'?200:403,html:'<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CBM report</title><body style="font:18px system-ui;max-width:700px;margin:60px auto;padding:24px"><h1>Rapporto tecnico / Technician report</h1><p>'+esc(messages[access.status]||'Link non valido o scaduto / Invalid or expired link. Request a new link from the FM.')+'</p></body></html>'}}];
}
const base=String($env.IFC_SERVICE_URL||'').replace(/\/+$/,'');
const template=await this.helpers.httpRequest({method:'GET',url:base+'/reports/template',json:true,timeout:15000});
const auth=$('Technician Report Page').first().json.query;
const context={fields:access.fields,ticketId:access.ticketId,token:auth.token,submitUrl:'https://bonanza-progress-hangover.ngrok-free.dev/webhook/cbm-technician-report'};
return [{json:{httpCode:200,html:template.html.replace('<!-- CBM_BOUND_CONTEXT -->','<script id="cbm-bound-context" type="application/json">'+JSON.stringify(context).replace(/</g,'\\u003c')+'</script>')}}];

const access=$json.context;
if(access.status!=='OK')return [{json:{result:access}}];
try{
 const body=$('Submit Technician Report').first().json.body;
 const report=JSON.parse(String(body.report||''));
 const limits={findings:[1,3000],work_performed:[20,6000],materials:[0,2000],checks:[1,4000],remaining_issues:[1,4000],photo_caption:[0,500]};
 for(const [key,[min,max]] of Object.entries(limits)){
  if(typeof (report[key]??'')!=='string')throw new Error('Invalid '+key);
  report[key]=String(report[key]||'').trim();if(report[key].length<min||report[key].length>max)throw new Error('Check '+key);
 }
 if(report.declaration!==true||!['PASSED','FAILED','NOT_PERFORMED'].includes(report.check_result)||!['COMPLETED','PARTIAL','NOT_COMPLETED'].includes(report.outcome)||!/^\d{4}-\d{2}-\d{2}$/.test(report.work_date))throw new Error('Complete the date, results and confirmation');
 for(const [key,value] of Object.entries(access.fields))if(String(report[key]??'')!==String(value??''))throw new Error('Ticket details changed. Reopen the assigned link.');
 if(typeof body.pdfB64!=='string'||body.pdfB64.length>12*1024*1024||!/^[A-Za-z0-9+/]+={0,2}$/.test(body.pdfB64))throw new Error('Invalid report PDF');
 const buf=Buffer.from(body.pdfB64,'base64');
 if(buf.length>8*1024*1024||buf.subarray(0,5).toString()!=='%PDF-')throw new Error('Report must be a PDF up to 8 MiB');
 const base=String($env.IFC_SERVICE_URL||'').replace(/\/+$/,'');
 const parsed=await this.helpers.httpRequest({method:'POST',url:base+'/reports/extract',json:true,body:{pdfB64:body.pdfB64},timeout:60000});
 const normalize=v=>String(v||'').normalize('NFC').replace(/\s+/g,' ').trim();
 for(const key of ['technician_name','technician_email','reported_issue','work_performed','checks'])if(!normalize(parsed.text).includes(normalize(report[key])))throw new Error('PDF does not match the form. Generate it again.');
 if(report.photoSupplied===true&&(parsed.photo_status!=='OK'||!report.photo_caption))throw new Error('The intervention photo could not be read. Select it again.');
 const safe={schema_version:'1.0',...access.fields,work_date:report.work_date,check_result:report.check_result,outcome:report.outcome,declaration:true,photoSupplied:report.photoSupplied===true};
 for(const key of Object.keys(limits))safe[key]=report[key];
 const request={ticketId:access.ticketId,token:body.token,pdf_sha256:require('crypto').createHash('sha256').update(buf).digest('hex'),report:safe};
 return [{json:{valid:true,request},binary:{data:await this.helpers.prepareBinaryData(buf,'TICKET-'+access.ticketId+'.pdf','application/pdf')}}];
}catch(e){return [{json:{valid:false,result:{status:'INVALID',detail:String(e.message||e).slice(0,240)}}}];}

const result=$json.result||$json.context||$json;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const success=result.status==='SUBMITTED';
const messages={SUBMITTED:'Rapporto caricato in Drive. WF2 lo elaborerà e richiederà la decisione del FM. Il ticket non è ancora chiuso. / Report uploaded to Drive. WF2 will assess it and request the FM decision. The ticket is not closed yet.',UNCONFIRMED:'Caricamento da verificare: contatta il FM. Non inviare una seconda copia finché il primo tentativo non è stato verificato. / Upload needs verification: contact the FM before sending another copy.',INVALID:'Controlla il modulo e riprova / Check the form and try again.',NOT_OPEN:'Il ticket non accetta rapporti in questo stato / The ticket is not accepting reports in its current state.',UNAVAILABLE:'Link non valido o scaduto / Invalid or expired link.'};
const html='<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CBM report submission</title><body style="font:18px system-ui;max-width:740px;margin:60px auto;padding:24px;color:#183b38"><p>CBM · RAPPORTO TECNICO</p><h1>'+(success?'Rapporto inviato / Report submitted':'Invio non completato / Submission incomplete')+'</h1><p>'+esc(messages[result.status]||messages.UNAVAILABLE)+'</p>'+(result.ticketId?'<p>Ticket #'+esc(result.ticketId)+'</p>':'')+(result.submissionId?'<p>Submission: '+esc(result.submissionId)+'</p>':'')+(result.detail?'<p>'+esc(result.detail)+'</p>':'')+'</body></html>';
return [{json:{html,httpCode:success?200:result.status==='INVALID'?422:409}}];
